 async void HeaderReboot_Click(object sender,RoutedEventArgs e)=>await Guard(async()=>{var row=Current();if(HeaderRebootJob(row)!=null){Notify("Перезагрузка уже назначена. Для изменения сначала отмените её.");return;}var window=new Window{Owner=this,Title="Перезагрузка · "+row.Host,Width=540,SizeToContent=SizeToContent.Height,WindowStartupLocation=WindowStartupLocation.CenterOwner};var panel=new StackPanel{Margin=new(20)};window.Content=panel;panel.Children.Add(RebootDialogEvidence40(row));panel.Children.Add(new TextBlock{Text="Только текущий компьютер: "+row.Host,FontWeight=FontWeights.SemiBold});panel.Children.Add(new TextBlock{Text="Остальные галочки не влияют. Сохраните документы на клиенте.",TextWrapping=TextWrapping.Wrap});panel.Children.Add(new TextBlock{Text="Задержка в секундах (0–86400)"});var delay=new TextBox{Text="60"};panel.Children.Add(delay);var message=new TextBox{Text="Плановая перезагрузка. Сохраните документы.",MaxLength=400};panel.Children.Add(message);var force=new CheckBox{Content="Принудительно закрыть приложения (возможна потеря данных)"};panel.Children.Add(force);var scan=new CheckBox{Content="Продолжить обслуживание после перезагрузки",IsChecked=AutoServiceEnabled,IsEnabled=false,ToolTip="Определяется общим переключателем автообслуживания"};panel.Children.Add(scan);var actions=new WrapPanel();panel.Children.Add(actions);var run=new Button{Content="Перезагрузить",IsDefault=true};actions.Children.Add(run);actions.Children.Add(new Button{Content="Отмена",IsCancel=true});run.Click+=(s,a)=>{if(!int.TryParse(delay.Text,out var seconds)||seconds<0||seconds>86400){MessageBox.Show(window,"Укажите задержку 0–86400 секунд.");return;}window.DialogResult=true;};if(window.ShowDialog()!=true)return;
