 public static string HeaderRebootCode(int wait,string message,bool force){
  if(wait<0||wait>86400)throw new ArgumentOutOfRangeException(nameof(wait));
  string text=message.Replace("\r"," ").Replace("\n"," ");
  return "Write-Output "+PowerShellBridge.Literal("Перезагрузка через "+wait+" сек: "+text)+";"+
   "$dcPlanPath=Join-Path $env:ProgramData 'DomainConsoleCSharp\\{{REBOOT_JOB}}\\reboot-plan.json';$dcNow=[DateTime]::UtcNow;$dcOs=Get-CimInstance Win32_OperatingSystem -ErrorAction Stop;$dcPlan=@{RequestedUtc=$dcNow.ToString('o');DueUtc=$dcNow.AddSeconds("+wait+").ToString('o');BeforeBootUtc=$dcOs.LastBootUpTime.ToUniversalTime().ToString('o')};function Save-DcRebootPlan {$dcPlan|ConvertTo-Json -Compress|Set-Content -LiteralPath $dcPlanPath -Encoding UTF8};Save-DcRebootPlan;"+
   "$dcCancelPath=Join-Path $env:ProgramData 'DomainConsoleCSharp\\{{REBOOT_JOB}}\\reboot-cancel.flag';$dcDeadline=$dcNow.AddSeconds("+wait+");"+
   (wait>0?"try { & msg.exe * /time:"+Math.Min(wait,300)+" "+PowerShellBridge.Literal("Перезагрузка через "+wait+" секунд. "+text)+" 2>$null | Out-Null } catch { Write-Output 'Сообщение пользователю доставить не удалось.' };while([DateTime]::UtcNow -lt $dcDeadline){if(Test-Path -LiteralPath $dcCancelPath){$dcPlan.Cancelled=$true;Save-DcRebootPlan;Write-Output 'Перезагрузка отменена';exit 0};Start-Sleep -Milliseconds 200};":"")+
   "if(Test-Path -LiteralPath $dcCancelPath){$dcPlan.Cancelled=$true;Save-DcRebootPlan;Write-Output 'Перезагрузка отменена';exit 0};"+
   "$dcPlan.DispatchUtc=[DateTime]::UtcNow.ToString('o');Save-DcRebootPlan;try{& shutdown.exe /r /t 0 "+(force?"/f ":"")+"/c "+PowerShellBridge.Literal(text)+";$dcExit=$LASTEXITCODE;$dcPlan.DispatchExitCode=$dcExit;if($dcExit -ne 0){$dcPlan.DispatchError='shutdown: код '+$dcExit};Save-DcRebootPlan;if($dcExit -ne 0){exit $dcExit};Write-Output 'Команда перезагрузки принята Windows. Факт перезагрузки проверяется по времени загрузки.'}catch{$dcPlan.DispatchError=$_.Exception.Message;Save-DcRebootPlan;throw}";
 }
 RemoteJob? HeaderRebootJob(ComputerRow row)=>HostJobs39(row.Host).FirstOrDefault(x=>x.Job.Name=="Перезагрузка текущего компьютера"&&x.Target.Status is "Queued" or "Sending" or "Submitted" or "Running").Job;
 async void HeaderAbortReboot_Click(object sender,RoutedEventArgs e)=>await Guard(async()=>{var row=Current();var job=HeaderRebootJob(row);if(job==null){Notify("Нет назначенной этой кнопкой перезагрузки.");return;}if(MessageBox.Show(this,"Отменить перезагрузку "+row.Host+"?", "Перезагрузка",MessageBoxButton.YesNo)!=MessageBoxResult.Yes)return;var target=job.Targets.First(t=>t.Host.Equals(row.Host,StringComparison.OrdinalIgnoreCase));if(target.Status=="Queued"&&target.State==null){var keep=queue.Where(x=>x.Job!=job||x.Target!=target).ToList();queue.Clear();foreach(var item in keep)queue.Enqueue(item);target.Status="Cancelled";Save();RefreshOutcomes();}else{await remote.RequestRebootCancellation(target,job.Id);await Task.Delay(350);await Poll(new ComputerRow(target,job.Id));}Notify("Запрошена отмена назначенной перезагрузки. Проверьте результат задания.");});
 async Task SubmitHeaderReboot(ComputerRow row,string code,int delaySeconds,bool scanAfter=false){if(!await EnsureEndpointCredentials(new(){row}))return;historyViewId="";var job=new RemoteJob{ScanAfterReboot=AutoServiceEnabled,Name="Перезагрузка текущего компьютера",OutputChannel="Commands",IndependentControl=true,Steps=new(){new(){Name="Перезагрузка текущего компьютера",Kind="PowerShell",Code=code}},Targets=new(){new(){Name=row.Name,Host=row.Host,OU=row.OU,OS=row.OS,Status="Queued"}}};job.Targets[0]=ConnectionStore.Capture(row.Target);job.Targets[0].Status="Queued";job.Targets[0].State=null;job.Targets[0].Output="";job.Steps[0].Code=job.Steps[0].Code.Replace("{{REBOOT_JOB}}",job.Id);WatchReboot(job,row.Host,delaySeconds);History.Insert(0,job);queue.Enqueue((job,job.Targets[0]));confirmedJobs.Add(job.Id+row.Host);RememberComputer(row.Host);Save();Sync(job);ShowCurrent();await SendQueue(job.Id);}
